resources.preRequestScript:
if (!insomnia.environment.get('refreshTokenAnterior')) throw new Error('Variavel obrigatoria vazia: refreshTokenAnterior');
const started = Number(insomnia.environment.get('refreshAdminRotatedAt') || 0);
const elapsed = started ? Date.now() - started : 0;
const wait = Math.max(0, 31000 - elapsed);
if (wait > 29000) throw new Error('Replay tardio expirou; execute a partir da rotacao inicial.');
if (wait > 0) await new Promise(resolve => setTimeout(resolve, wait));

